import javax.tools.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.util.*;

/** Shipping preview-to-still curve helper against explicit Camera2 capability/result fixtures. */
public final class StillToneRegression {
    static void write(Path root,List<String> files,String path,String source)throws Exception{Path file=root.resolve(path);Files.createDirectories(file.getParent());Files.write(file,source.getBytes(StandardCharsets.UTF_8));files.add(file.toString());}
    public static void main(String[] args)throws Exception{
        Path root=Paths.get(args[0]),dir=root.resolve("build/still-tone-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);List<String> files=new ArrayList<>();
        write(dir,files,"android/hardware/camera2/params/TonemapCurve.java","package android.hardware.camera2.params;public class TonemapCurve{final float[][] points;public TonemapCurve(float[] r,float[] g,float[] b){points=new float[][]{r.clone(),g.clone(),b.clone()};}public int getPointCount(int c){return points[c].length/2;}public void copyColorCurve(int c,float[] out,int at){System.arraycopy(points[c],0,out,at,points[c].length);}}");
        write(dir,files,"android/hardware/camera2/CaptureRequest.java","package android.hardware.camera2;import java.util.*;import android.hardware.camera2.params.TonemapCurve;public class CaptureRequest{public static final int TONEMAP_MODE_CONTRAST_CURVE=0;public static class Key<T>{}public static final Key<Integer> TONEMAP_MODE=new Key<>();public static final Key<TonemapCurve> TONEMAP_CURVE=new Key<>();public static class Builder{public Map<Key<?>,Object> values=new HashMap<>();public Map<String,Map<Key<?>,Object>> physical=new HashMap<>();public <T>void set(Key<T> k,T v){values.put(k,v);}public <T>void setPhysicalCameraKey(Key<T> k,T v,String id){physical.computeIfAbsent(id,n->new HashMap<>()).put(k,v);}}}");
        write(dir,files,"android/hardware/camera2/CameraCharacteristics.java","package android.hardware.camera2;import java.util.*;public class CameraCharacteristics{public static final int REQUEST_AVAILABLE_CAPABILITIES_MANUAL_POST_PROCESSING=2;public static class Key<T>{}public static final Key<int[]> REQUEST_AVAILABLE_CAPABILITIES=new Key<>(),TONEMAP_AVAILABLE_TONE_MAP_MODES=new Key<>();public static final Key<Integer> TONEMAP_MAX_CURVE_POINTS=new Key<>();public Map<Key<?>,Object> values=new HashMap<>();public List<CaptureRequest.Key<?>> keys=new ArrayList<>(),physical=new ArrayList<>();public <T>void set(Key<T> k,T v){values.put(k,v);}@SuppressWarnings(\"unchecked\")public <T>T get(Key<T> k){return (T)values.get(k);}public List<CaptureRequest.Key<?>> getAvailableCaptureRequestKeys(){return keys;}public List<CaptureRequest.Key<?>> getAvailablePhysicalCameraRequestKeys(){return physical;}}");
        write(dir,files,"android/hardware/camera2/CaptureResult.java","package android.hardware.camera2;import java.util.*;import android.hardware.camera2.params.TonemapCurve;public class CaptureResult{public static class Key<T>{}public static final Key<Long> SENSOR_EXPOSURE_TIME=new Key<>();public static final Key<Integer> SENSOR_SENSITIVITY=new Key<>();public static final Key<TonemapCurve> TONEMAP_CURVE=new Key<>();public Map<Key<?>,Object> values=new HashMap<>();public <T>CaptureResult set(Key<T> k,T v){values.put(k,v);return this;}@SuppressWarnings(\"unchecked\")public <T>T get(Key<T> k){return (T)values.get(k);}}");
        write(dir,files,"com/silverroom/camera/ToneProbe.java",probe());
        for(String name:new String[]{"StillTone","ExposureMatch"})files.add(root.resolve("src/com/silverroom/camera/"+name+".java").toString());List<String> opts=new ArrayList<>(Arrays.asList("--release","8","-encoding","UTF-8","-d",classes.toString()));opts.addAll(files);if(ToolProvider.getSystemJavaCompiler().run(null,null,null,opts.toArray(new String[0]))!=0)throw new AssertionError("Still-tone fixture compile");
        try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},null)){try{for(Object label:(List<?>)loader.loadClass("com.silverroom.camera.ToneProbe").getMethod("run").invoke(null))System.out.println("PASS "+label);}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError("Actual still-tone helper",e.getCause());}}
    }
    static String probe(){return "package com.silverroom.camera;import java.util.*;import android.hardware.camera2.*;import android.hardware.camera2.params.*;public class ToneProbe{static List<String> passed=new ArrayList<>();static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);passed.add(label);}static CameraCharacteristics caps(){CameraCharacteristics c=new CameraCharacteristics();c.set(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES,new int[]{2});c.set(CameraCharacteristics.TONEMAP_AVAILABLE_TONE_MAP_MODES,new int[]{0,1});c.set(CameraCharacteristics.TONEMAP_MAX_CURVE_POINTS,8);c.keys.add(CaptureRequest.TONEMAP_MODE);c.keys.add(CaptureRequest.TONEMAP_CURVE);c.physical.addAll(c.keys);return c;}static TonemapCurve curve(float... points){return new TonemapCurve(points,points,points);}public static List<String> run(){ExposureMatch.Sample sample=new ExposureMatch.Sample(0,0f,10000000L,200,33333333L,2f,2,1000);TonemapCurve curve=curve(0,0,.2f,.42f,.5f,.75f,1,1);CaptureResult result=new CaptureResult().set(CaptureResult.SENSOR_EXPOSURE_TIME,10000000L).set(CaptureResult.SENSOR_SENSITIVITY,200).set(CaptureResult.TONEMAP_CURVE,curve);StillTone.Snapshot tone=StillTone.read(result,sample);check(tone!=null&&StillTone.match(tone,sample)==tone,\"Reported preview curve is frozen only with its exact accepted exposure sample\");ExposureMatch.Sample newer=new ExposureMatch.Sample(0,0f,10000000L,200,33333333L,2f,2,1001);check(StillTone.match(tone,newer)==null&&StillTone.match(tone,null)==null,\"Older curves cannot accompany another exposure snapshot even when ISO and shutter happen to match\");result.set(CaptureResult.SENSOR_SENSITIVITY,100);check(StillTone.read(result,sample)==null&&StillTone.read(null,sample)==null,\"Missing or mismatched preview results cannot manufacture a reusable tone curve\");CameraCharacteristics owner=caps(),sensor=caps();CaptureRequest.Builder b=new CaptureRequest.Builder();check(StillTone.apply(b,tone,owner,sensor,null)&&b.values.get(CaptureRequest.TONEMAP_CURVE)==curve&&b.values.get(CaptureRequest.TONEMAP_MODE).equals(0)&&b.values.size()==2,\"Supported standalone still copies the real preview curve without changing sensor exposure\");b=new CaptureRequest.Builder();check(StillTone.apply(b,tone,owner,sensor,\"4\")&&b.physical.get(\"4\").get(CaptureRequest.TONEMAP_CURVE)==curve&&b.physical.get(\"4\").get(CaptureRequest.TONEMAP_MODE).equals(0),\"Physical output receives the same exact curve as its logical request\");owner.physical.remove(CaptureRequest.TONEMAP_CURVE);b=new CaptureRequest.Builder();check(!StillTone.apply(b,tone,owner,sensor,\"4\")&&b.values.isEmpty()&&b.physical.isEmpty(),\"Missing physical tone keys leave the original capture request untouched\");owner=caps();sensor.set(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES,new int[0]);check(!StillTone.apply(b,tone,owner,sensor,null),\"A sensor without manual post-processing retains its supported original tone path\");sensor=caps();sensor.set(CameraCharacteristics.TONEMAP_AVAILABLE_TONE_MAP_MODES,new int[]{1});check(!StillTone.apply(b,tone,owner,sensor,null),\"FAST-only sensors are not forced into unsupported custom curves\");sensor=caps();owner.set(CameraCharacteristics.TONEMAP_MAX_CURVE_POINTS,2);check(!StillTone.apply(b,tone,owner,sensor,null),\"Curve limits are checked on both sensor and logical owner without lossy truncation\");check(!StillTone.valid(curve(0,0,.5f,.8f,1,.6f),8)&&!StillTone.valid(curve(0,0,.5f,.4f,.5f,.8f,1,1),8)&&!StillTone.valid(curve(0,0,1,Float.NaN),8),\"Malformed or nonmonotonic curves are rejected before a request is modified\");check(!StillTone.valid(curve(.1f,0,1,1),8)&&!StillTone.valid(curve(0,0,.9f,1),8)&&StillTone.valid(curve(0,.02f,1,.96f),8),\"Input endpoints cover the full range while genuine lifted blacks and soft highlights are preserved\");b=new CaptureRequest.Builder();check(!StillTone.apply(b,null,caps(),caps(),null)&&b.values.isEmpty(),\"Absent tone metadata does not add a guessed brightness or synthetic curve\");return passed;}}";}
}
